  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 9, $j$3.1 Elections, Voting and Political Parties$j$, $j${"readings": [{"title": "Proverbs 29 (King James Version)", "url": "/portal/bible/Proverbs/29"}], "body": "In a republic, elections are how citizens choose leaders and hold them accountable. Voting rights grew over time. The Fifteenth Amendment (1870) barred denying the vote because of race, the Nineteenth (1920) gave women the vote, the Twenty Fourth (1964) ended poll taxes in federal elections, and the Twenty Sixth (1971) lowered the voting age to 18. The Voting Rights Act of 1965 outlawed practices such as literacy tests that kept Black citizens from voting.\n\nTo vote in Florida, a person must be a United States citizen, a Florida resident and at least 18 years old, and must register by the deadline before an election. A person may preregister at age 16 or 17. Federal general elections are held on the Tuesday after the first Monday in November.\n\nA political party is a group of people who organize to win elections and shape policy. The United States has two major parties, the Democratic Party and the Republican Party, along with smaller parties and independents. Primary elections choose each party's candidates, and the general election chooses the winner. Candidates raise money, campaign and debate, and voters should study each candidate's record, ask questions and judge claims with care, as you learned when you studied the Bereans in Acts 17:11.\n\nVoting is a duty of citizenship, not a way to idolize a person or party. Proverbs 29:2 says, When the righteous are in authority, the people rejoice.\n\nYour task: (1) Name three amendments that expanded the right to vote. (2) State the requirements to vote in Florida. (3) Explain the difference between a primary and a general election.\n\nFlorida standards: SS.912.CG.3.1, SS.912.CG.3.2.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.CG.3.1, SS.912.CG.3.2", "script": "Welcome to our last unit. Listen, this one is about you. In a republic, elections are how citizens choose leaders and hold them accountable.\n\nVoting rights grew over time. The Fifteenth Amendment in 1870 barred denying the vote because of race. The Nineteenth in 1920 gave women the vote. The Twenty Fourth in 1964 ended poll taxes in federal elections. The Twenty Sixth in 1971 lowered the voting age to eighteen. And the Voting Rights Act of 1965 outlawed practices like literacy tests that kept Black citizens from voting.\n\nNow watch this. To vote in Florida, you must be a United States citizen, a Florida resident, at least eighteen, and registered by the deadline. You can preregister at sixteen or seventeen. Federal general elections happen on the Tuesday after the first Monday in November.\n\nLook at the parties. A political party is a group organized to win elections and shape policy. We have two major parties and some smaller ones. Primary elections choose each party's candidates, and the general election chooses the winner.\n\nStudy each candidate's record, ask questions and test claims, like the Bereans in Acts 17:11. Voting is a duty of citizenship, not worship of a person or a party.\n\nYour task is to name three voting amendments, state the Florida requirements, and explain primary and general elections. Take the four question check. Vote with wisdom. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.1 Elections, Voting and Political Parties$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 10, $j$3.2 Civil Liberties and Civil Rights$j$, $j${"readings": [{"title": "Acts 5 (King James Version)", "url": "/portal/bible/Acts/5"}], "body": "Civil liberties are freedoms protected from government interference, such as speech, religion and a fair trial. Civil rights are the rights of equal treatment under the law, such as the right not to be discriminated against because of race or sex. The Fourteenth Amendment applies many protections to the states through its due process and equal protection clauses.\n\nReligion has two protections in the First Amendment. The Establishment Clause says Congress shall make no law respecting an establishment of religion, so government may not set up an official church. The Free Exercise Clause protects a person's right to worship and live by his faith. Together they protect both believers and the freedom of conscience of every citizen.\n\nStudents have rights, too. In Tinker v. Des Moines (1969), the Supreme Court held that students do not shed their rights at the schoolhouse gate, though schools may limit speech that substantially disrupts learning. In Miranda v. Arizona (1966), the Court required police to tell a suspect of the right to remain silent and the right to a lawyer.\n\nThe civil rights movement used courts, laws and peaceful protest to end legal segregation. Important victories include Brown v. Board of Education (1954), the Civil Rights Act of 1964, which banned discrimination in public places and employment, and the Voting Rights Act of 1965.\n\nActs 5:29 reminds believers, We ought to obey God rather than men, and Galatians 3:28 says that in Christ there is neither Jew nor Greek, bond nor free, male nor female, for all are one.\n\nYour task: (1) Explain the difference between civil liberties and civil rights. (2) Explain the Establishment Clause and the Free Exercise Clause. (3) Name two civil rights victories.\n\nFlorida standards: SS.912.CG.2.1, SS.912.CG.2.2.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.CG.2.1, SS.912.CG.2.2", "script": "Now we study rights. Listen, there are two ideas here and they are different. Civil liberties are freedoms protected from government interference, like speech, religion and a fair trial. Civil rights are the right to equal treatment under the law, such as not being discriminated against because of race or sex. The Fourteenth Amendment applies many protections to the states.\n\nNow watch this. The First Amendment protects religion in two ways. The Establishment Clause says government may not set up an official church. The Free Exercise Clause protects your right to worship and live by your faith. Together they protect believers and the freedom of conscience of every citizen.\n\nLook at students. In Tinker versus Des Moines in 1969, the Supreme Court said students do not shed their rights at the schoolhouse gate. In Miranda versus Arizona in 1966, the Court required police to tell a suspect of the right to remain silent and the right to a lawyer.\n\nThe civil rights movement used courts, laws and peaceful protest. Brown versus Board of Education in 1954. The Civil Rights Act of 1964. The Voting Rights Act of 1965.\n\nActs 5:29, we ought to obey God rather than men. And Galatians 3:28 says we are all one in Christ.\n\nYour task is to explain civil liberties and civil rights, explain the two religion clauses, and name two victories. Take the four question check. Defend the rights of all. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.2 Civil Liberties and Civil Rights$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 11, $j$3.3 Media, Public Opinion and Interest Groups$j$, $j${"readings": [{"title": "Proverbs 18 (King James Version)", "url": "/portal/bible/Proverbs/18"}], "body": "Citizens form opinions by what they hear from family, church, school, friends and the media. The media includes newspapers, television, radio, websites and social media. A free press is a check on government, because reporters can expose wrongdoing. It also has duties: to tell the truth, to separate news from opinion, and to correct mistakes.\n\nMedia literacy is the skill of judging information. Ask who made it and why, what evidence is given, whether other reliable sources agree, whether the headline matches the story, and whether it is news, opinion or advertising. Beware of bias, rumor, edited images and posts designed to make you angry. Proverbs 18:13 says, He that answereth a matter before he heareth it, it is folly and shame unto him.\n\nPublic opinion polls ask a sample of people their views. A good poll uses a random and representative sample, asks fair questions without leading words, and reports a margin of error.\n\nInterest groups are organizations of people with a shared concern who try to influence government. They lobby lawmakers, endorse candidates, take part in court cases and educate the public. Political action committees raise and spend money in elections. James Madison, in Federalist No. 10, warned about factions, groups that put their own interest above the good of all, and argued that a large republic with many groups helps keep any single faction from taking control. Churches and nonprofits also speak up for the poor, as Proverbs 31:9 says, Open thy mouth, judge righteously, and plead the cause of the poor and needy.\n\nYour task: (1) Give four questions for judging a news story. (2) List three features of a good poll. (3) Explain what an interest group does.\n\nFlorida standards: SS.912.CG.3.2, SS.912.CG.3.3.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.CG.3.2, SS.912.CG.3.3", "script": "Now we study how people shape government. Listen, citizens form opinions from family, church, school, friends and the media. The media includes newspapers, television, radio, websites and social media. A free press checks government, because reporters can expose wrongdoing. But the press has duties too. Tell the truth. Separate news from opinion. Correct mistakes.\n\nNow watch this. Media literacy is the skill of judging information. Ask who made it and why. What evidence does it give? Do other reliable sources agree? Does the headline match the story? Is it news, opinion or an ad? Beware of rumor, edited images and posts made to make you angry. Proverbs 18:13 says, He that answereth a matter before he heareth it, it is folly and shame unto him.\n\nLook at polls. A good poll uses a random and representative sample, asks fair questions without leading words, and reports a margin of error.\n\nThen interest groups. These are organizations with a shared concern who try to influence government. They lobby, endorse candidates, join court cases and educate the public. James Madison, in Federalist Number 10, warned about factions that put their own interest above the common good.\n\nChurches and nonprofits can also plead the cause of the poor, as Proverbs 31:9 says. Your task is to give four questions for judging news, list three features of a good poll, and explain interest groups. Take the four question check. Think before you share. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.3 Media, Public Opinion and Interest Groups$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 12, $j$3.4 Citizenship, Duty and Faith in Public Life$j$, $j${"readings": [{"title": "Matthew 22 (King James Version)", "url": "/portal/bible/Matthew/22"}], "body": "A citizen is a member of a nation with rights and duties. Most people become citizens by birth in the United States or to citizen parents. Others become citizens through naturalization, which requires lawful permanent residence, a period of residence, a test of English and civics, good moral character and an oath of allegiance.\n\nCitizenship carries rights, such as voting, free speech, a fair trial and the protection of the law. It also carries responsibilities. Some are legal duties: obey the laws, pay taxes, serve on a jury when called, and, for young men, register for the Selective Service at age 18. Others are civic responsibilities that are not required by law but make a free society work: vote, stay informed, volunteer, respect others' rights and serve the community.\n\nChristians have a double citizenship. Philippians 3:20 says our conversation is in heaven, and yet Scripture asks us to be good citizens on earth. Jesus said in Matthew 22:21, Render therefore unto Caesar the things which are Caesar's; and unto God the things that are God's. Titus 3:1 says to be subject to principalities and powers, to obey magistrates, and to be ready to every good work. 1 Peter 2:17 says, Honour all men. Love the brotherhood. Fear God. Honour the king. And when government commands what God forbids, Acts 5:29 reminds us that we ought to obey God rather than men, which believers have done peacefully and respectfully throughout history.\n\nFaith in public life means speaking the truth in love, serving the poor, praying for leaders, and respecting neighbors who hold different views, because the same Constitution protects everyone's conscience.\n\nYour task: (1) Name two ways to become a citizen. (2) List three legal duties and three civic responsibilities. (3) Explain how Matthew 22:21 and Acts 5:29 guide a Christian citizen.\n\nFlorida standards: SS.912.CG.2.2, SS.912.CG.3.3.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.CG.2.2, SS.912.CG.3.3", "script": "Welcome to our final lesson. Listen, a citizen is a member of a nation with rights and duties. Most people are citizens by birth in the United States or to citizen parents. Others become citizens by naturalization. That requires lawful permanent residence, a period of residence, a test of English and civics, good moral character and an oath of allegiance.\n\nNow watch this. Citizenship carries rights. Voting, free speech, a fair trial, and the protection of the law. It also carries responsibilities. Legal duties include obeying the laws, paying taxes, serving on a jury when called, and for young men, registering for the Selective Service at eighteen. Civic responsibilities are not required by law, but they make a free society work. Vote. Stay informed. Volunteer. Respect the rights of others. Serve your community.\n\nLook at the Christian citizen. Philippians 3:20 says our conversation is in heaven, yet we are called to be good citizens on earth. Jesus said, Render unto Caesar the things which are Caesar's, and unto God the things that are God's. Titus 3:1 says to be ready to every good work. First Peter 2:17, honour all men, love the brotherhood, fear God, honour the king. And Acts 5:29, if government commands what God forbids, we ought to obey God rather than men, peacefully and respectfully.\n\nFaith in public life means speaking the truth in love, serving the poor, praying for leaders and respecting neighbors who differ. The same Constitution protects everyone's conscience.\n\nYour task is to name two ways to become a citizen, list duties and responsibilities, and explain Matthew 22:21 and Acts 5:29. Take the four question check. Be a citizen who serves. Well done on finishing the course. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.4 Citizenship, Duty and Faith in Public Life$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 3, $j$Assessment 3: The Citizen and the Republic$j$, $j${"prompt": "Write a report of at least 300 words on citizenship in the American republic. Use complete sentences and label each part. Micah 6:8 says, He hath shewed thee, O man, what is good; and what doth the LORD require of thee, but to do justly, and to love mercy, and to walk humbly with thy God?\n\nPart 1: Explain how voting rights expanded, naming at least three amendments or laws, and state the requirements to vote in Florida.\nPart 2: Explain the difference between civil liberties and civil rights and describe the two religion clauses of the First Amendment.\nPart 3: Describe how a citizen can judge news and polls, and explain what interest groups do.\nPart 4: List three legal duties and three civic responsibilities of citizens, and explain why each matters.\nPart 5: Explain how a Christian citizen can honor God and serve the nation, using at least one passage of Scripture in the King James Version.", "rubric": "100 points. Part 1: 20 points. Part 2: 20 points. Part 3: 20 points. Part 4: 20 points. Part 5: 15 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 3: The Citizen and the Republic$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 3, $j$Discussion 3: Faith, Citizenship and the Common Good$j$, $j${"prompt": "Write a post of at least 120 words that (1) describes one way you will take part in your community or nation as a citizen now or when you turn 18, (2) explains why it is important to respect people who hold different political views, (3) tells how you will judge news and social media before you share it, and (4) connects your answer to Jeremiah 29:7, which says, And seek the peace of the city whither I have caused you to be carried away captives, and pray unto the LORD for it: for in the peace thereof shall ye have peace. Then write a respectful reply of at least 40 words to another student's post, or answer this question: What does it mean to be a good citizen and a faithful Christian at the same time? Keep your tone kind and respectful of other views."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 3: Faith, Citizenship and the Common Good$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 11, $j$Check 3.1: Elections, Voting and Political Parties$j$, $j${"questions": [{"q": "Which amendment gave women the right to vote?", "options": ["The Tenth", "The Nineteenth", "The Fifteenth", "The Twenty Sixth"]}, {"q": "The Twenty Sixth Amendment set the voting age at:", "options": ["25", "21", "18", "16"]}, {"q": "A primary election is used to:", "options": ["Elect the President directly", "Choose a party's candidates", "Pass amendments", "Appoint judges"]}, {"q": "To vote in Florida you must be:", "options": ["A citizen, a resident, 18 and registered", "Only a resident", "A property owner", "A party member"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.1: Elections, Voting and Political Parties$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,2,1,0}'::int[], array[$j$The Nineteenth was ratified in 1920.$j$,$j$It was ratified in 1971.$j$,$j$Primaries narrow the field for the general election.$j$,$j$These are the basic requirements.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.1: Elections, Voting and Political Parties$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 12, $j$Check 3.2: Civil Liberties and Civil Rights$j$, $j${"questions": [{"q": "The Establishment Clause says government may not:", "options": ["Allow worship", "Tax churches only", "Set up an official church", "Protect the press"]}, {"q": "Civil rights primarily concern:", "options": ["Foreign treaties", "Equal treatment under the law", "Taxes", "Elections for judges"]}, {"q": "Miranda v. Arizona requires police to inform suspects of:", "options": ["The right to a free home", "The right to remain silent and to a lawyer", "The right to vote", "The right to bail"]}, {"q": "The Civil Rights Act of 1964 banned:", "options": ["Discrimination in public places and employment", "State governments", "Federal taxes", "The draft"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.2: Civil Liberties and Civil Rights$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,1,1,0}'::int[], array[$j$It bars an official national religion.$j$,$j$Civil rights guarantee equal treatment.$j$,$j$These are the Miranda warnings.$j$,$j$It outlawed discrimination based on race, color, religion, sex and national origin.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.2: Civil Liberties and Civil Rights$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 13, $j$Check 3.3: Media, Public Opinion and Interest Groups$j$, $j${"questions": [{"q": "Media literacy means:", "options": ["Avoiding all news", "Trusting every post", "Reading only headlines", "Judging information carefully"]}, {"q": "A good poll uses:", "options": ["Leading questions", "A random, representative sample", "One friend's opinion", "Only volunteers"]}, {"q": "An interest group is:", "options": ["A political office", "A court", "An organization that tries to influence government", "A branch of government"]}, {"q": "In Federalist No. 10, Madison warned about:", "options": ["Foreign trade", "The Bill of Rights", "Term limits", "Factions"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.3: Media, Public Opinion and Interest Groups$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,1,2,3}'::int[], array[$j$It means asking who made it, why, and what evidence supports it.$j$,$j$Sampling and fair wording make a poll reliable.$j$,$j$Interest groups lobby, endorse and educate.$j$,$j$He argued that a large republic helps control factions.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.3: Media, Public Opinion and Interest Groups$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 14, $j$Check 3.4: Citizenship, Duty and Faith in Public Life$j$, $j${"questions": [{"q": "Naturalization is the process by which:", "options": ["A judge is chosen", "A person born elsewhere becomes a citizen", "A law is passed", "A state joins the Union"]}, {"q": "Which is a legal duty of citizens?", "options": ["Attending rallies", "Paying taxes", "Running for office", "Volunteering"]}, {"q": "Jury duty is:", "options": ["Only for lawyers", "A legal duty when called", "Optional for everyone", "Only for judges"]}, {"q": "Matthew 22:21 teaches us to:", "options": ["Ignore government", "Obey no one", "Worship the state", "Give to Caesar what is Caesar's and to God what is God's"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.4: Citizenship, Duty and Faith in Public Life$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,1,1,3}'::int[], array[$j$It includes residence, a test and an oath.$j$,$j$Taxes, obeying laws and jury duty are legal duties.$j$,$j$Citizens must serve on a jury when summoned.$j$,$j$Jesus taught honest duty to both government and God.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.4: Citizenship, Duty and Faith in Public Life$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 15, $j$Unit Quiz 3: The Citizen and the Republic$j$, $j${"questions": [{"q": "The Fifteenth Amendment protected voting regardless of:", "options": ["Wealth", "Age", "Race", "Religion"]}, {"q": "A general election is held to:", "options": ["Appoint judges", "Pass amendments", "Choose the winner among party nominees", "Choose party candidates only"]}, {"q": "The Free Exercise Clause protects:", "options": ["A person's right to worship and live by faith", "An official church", "School lunches", "Taxes"]}, {"q": "Civil rights concern:", "options": ["Foreign trade", "Equal treatment under the law", "Court procedure only", "Taxes on goods"]}, {"q": "A reliable news story usually:", "options": ["Is written to make you angry", "Cites evidence and can be checked", "Has no author", "Uses only anonymous rumors"]}, {"q": "A legal duty of a citizen is:", "options": ["Volunteering", "Writing to the editor", "Serving on a jury when called", "Joining a party"]}, {"q": "Naturalization requires:", "options": ["Owning a home", "An oath of allegiance", "Birth in Florida", "A college degree"]}, {"q": "Acts 5:29 says we ought to obey:", "options": ["God rather than men", "Only the strongest", "Men rather than God", "No one"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 3: The Citizen and the Republic$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,2,0,1,1,2,1,0}'::int[], array[$j$It was ratified in 1870.$j$,$j$The general election decides who holds office.$j$,$j$It protects religious practice.$j$,$j$They guarantee equal treatment.$j$,$j$Reliable reporting can be verified.$j$,$j$Jury service is required when summoned.$j$,$j$Applicants take an oath after meeting other requirements.$j$,$j$When commands conflict, believers obey God.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 3: The Citizen and the Republic$j$ on conflict (item_id) do nothing;
